def validate_timezone(value: str):
    """Validates that the provided timezone string is a valid IANA timezone."""
    if value not in zoneinfo.available_timezones():
        raise ValidationError(f"'{value}' is not a valid IANA timezone.")

def clean(self):
        super().clean()
        # Ensure user belongs to the assigned tenant
        if self.created_by_id and self.tenant_id: # type: ignore
            if self.created_by.tenant_id != self.tenant_id: # type: ignore
                raise ValidationError("created_by user must belong to the specified tenant.")

        # Ensure start_time is before end_time if both are provided
        if self.start_time and self.end_time:
            if self.start_time > self.end_time:
                raise ValidationError("end_time must be greater than start_time.")

def update_status(
        tenant_id: UUID, todo_id: UUID, status: Todo.Status
    ) -> Optional[Todo]:
        """
        Updates only the status field of a Todo.

        Delegates to the generic `update` method with `status=status`.
        Returns the updated Todo instance, or None if not found.
        """
        return TodoRepository.update(tenant_id, todo_id, status=status)

def get_signature(node):
    """Return a readable signature for a function or method."""
    try:
        args = ast.unparse(node.args)
        return f"({args})"
    except Exception:
        return "()"

def extract_symbols(file_path):
    source = file_path.read_text(encoding="utf-8")

    try:
        tree = ast.parse(source, filename=str(file_path))
    except SyntaxError as exc:
        print(f"Skipping {file_path}: {exc}")
        return []

    relative_path = file_path.relative_to(ROOT).as_posix()
    symbols = []

    def visit(node, parents=()):
        if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            qualified_name = ".".join((*parents, node.name))

            if isinstance(node, ast.ClassDef):
                symbol_type = "class"
                signature = None
            else:
                symbol_type = (
                    "async_function"
                    if isinstance(node, ast.AsyncFunctionDef)
                    else "function"
                )
                signature = get_signature(node)

            symbols.append({
                "symbol": node.name,
                "qualified_name": qualified_name,
                "symbol_type": symbol_type,
                "file_path": relative_path,
                "start_line": node.lineno,
                "end_line": node.end_lineno,
                "signature": signature,
                "docstring": ast.get_docstring(node),
                "source": ast.get_source_segment(source, node),
                "calls": extract_calls(node) if not isinstance(node, ast.ClassDef) else [],
            })

            # Nested functions and class methods retain their parent scope.
            next_parents = (*parents, node.name)
        else:
            next_parents = parents

        for child in ast.iter_child_nodes(node):
            visit(child, next_parents)

    visit(tree)
    return symbols

