def extract_calls(node):
    """Extract raw function and method call expressions from an AST node."""
    calls = []

    for child in ast.walk(node):
        if not isinstance(child, ast.Call):
            continue

        try:
            call_name = ast.unparse(child.func)
        except Exception:
            continue

        calls.append({
            "name": call_name,
            "line": child.lineno,
        })

    return calls

def main():
    all_symbols = []

    for file_path in ROOT.rglob("*.py"):
        if any(part in EXCLUDED_DIRS for part in file_path.parts):
            continue

        all_symbols.extend(extract_symbols(file_path))

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(
        json.dumps(all_symbols, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )

    print(f"Indexed {len(all_symbols)} symbols")
    print(f"Saved index to: {OUTPUT.relative_to(ROOT)}")

