def build_symbol_lookup(symbols):
    """Index symbols by qualified name and simple name."""
    by_qualified_name = {}
    by_name = defaultdict(list)

    for symbol in symbols:
        by_qualified_name[symbol["qualified_name"]] = symbol
        by_name[symbol["symbol"]].append(symbol)

    return by_qualified_name, by_name

def load_json(path, default):
    if not path.exists():
        return default

    return json.loads(path.read_text(encoding="utf-8"))

def tokenize(text):
    return {
        token
        for token in re.findall(r"[a-zA-Z_][a-zA-Z0-9_]*", text.casefold())
        if token not in STOP_WORDS
    }

def retrieve_context(query, limit=5):
    symbols = load_json(INDEX_PATH, [])
    edges = load_json(GRAPH_PATH, [])

    if not symbols:
        raise RuntimeError(
            f"No symbols found. Run scripts/index_code.py first: {INDEX_PATH}"
        )

    query = query.casefold().strip()
    query_tokens = tokenize(query)

    if not query_tokens:
        raise ValueError("Query must contain searchable words.")

    # Rank all indexed symbols.
    ranked = []

    for symbol in symbols:
        score, reasons = score_symbol(symbol, query, query_tokens)

        if score > 0:
            ranked.append({
                "symbol": symbol,
                "score": score,
                "reasons": reasons,
            })

    ranked.sort(
        key=lambda item: (
            -item["score"],
            item["symbol"].get("qualified_name", ""),
        )
    )

    primary = ranked[:limit]
    primary_names = {
        item["symbol"]["qualified_name"]
        for item in primary
    }

    outgoing, incoming = build_graph_indexes(edges)

    # Expand one hop through resolved project calls.
    related_names = set()

    for name in primary_names:
        for edge in outgoing.get(name, []):
            related_names.add(edge["resolved_target"])

        for edge in incoming.get(name, []):
            related_names.add(edge["caller"])

    symbol_by_name = {
        symbol["qualified_name"]: symbol
        for symbol in symbols
    }

    # Don't duplicate primary results in the related section.
    related_names -= primary_names

    related_symbols = [
        symbol_by_name[name]
        for name in sorted(related_names)
        if name in symbol_by_name
    ]

    return primary, related_symbols, outgoing, incoming

def print_symbol(item, reasons=None, relation=None):
    print(f"\n{'=' * 72}")
    print(item.get("qualified_name", item.get("symbol", "Unknown")))
    print(
        f"Type: {item.get('symbol_type')} | "
        f"File: {item.get('file_path')} | "
        f"Lines: {item.get('start_line')}-{item.get('end_line')}"
    )

    if reasons:
        print("Match reasons: " + "; ".join(reasons))

    if relation:
        print("Context: " + relation)

    signature = item.get("signature")
    if signature:
        print(f"Signature: {item['symbol']}{signature}")

    docstring = item.get("docstring")
    if docstring:
        print(f"Docstring: {docstring}")

    source = item.get("source")
    if source:
        print("\nSource:")
        print(source)

def main():
    parser = argparse.ArgumentParser(
        description="Retrieve source context from the repository index."
    )
    parser.add_argument(
        "query",
        nargs="+",
        help="Natural-language question about the codebase",
    )
    parser.add_argument(
        "--limit",
        type=int,
        default=5,
        help="Maximum number of primary symbol matches (default: 5)",
    )
    args = parser.parse_args()

    if args.limit < 1:
        parser.error("--limit must be at least 1")

    query = " ".join(args.query)

    try:
        primary, related, outgoing, incoming = retrieve_context(
            query,
            limit=args.limit,
        )
    except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
        raise SystemExit(f"Error: {exc}") from exc

    print(f"Query: {query}")
    print(f"Primary matches: {len(primary)}")
    print(f"Related symbols: {len(related)}")

    if not primary:
        print(
            "\nNo symbols matched lexically. "
            "Try using a function name or domain term from the code."
        )
        return

    for result in primary:
        symbol = result["symbol"]

        print_symbol(
            symbol,
            reasons=result["reasons"],
        )

        name = symbol["qualified_name"]

        for edge in outgoing.get(name, []):
            print(
                f"\n  CALLS: {edge['resolved_target']} "
                f"({edge.get('target_file') or 'file unknown'}:"
                f"{edge.get('target_start_line') or '?'})"
            )

        for edge in incoming.get(name, []):
            print(
                f"\n  CALLED BY: {edge['caller']} "
                f"({edge.get('caller_file', 'file unknown')}:"
                f"{edge.get('line', '?')})"
            )

    if related:
        print("\n\n### Related source context")

        for symbol in related:
            print_symbol(
                symbol,
                relation="Included through a resolved call-graph relationship",
            )

