def invoke_with_skills(
    agent: Any,
    input_state: dict[str, Any],
    pinned_skills: Sequence[str] | None = None,
    **kwargs: Any,
) -> Any:
    """Invoke an agent with explicitly selected skills."""
    state = dict(input_state)

    if pinned_skills:
        state["pinned_skills"] = list(pinned_skills)

    return agent.invoke(state, **kwargs)

class PinSkillsMiddleware(AgentMiddleware):
    """Set the skills to inject before the agent's model call."""

    def __init__(self, pinned_skills: Sequence[str]) -> None:
        self.pinned_skills = list(pinned_skills)

    def before_agent(
        self,
        state: dict[str, Any],
        runtime: Any,
    ) -> dict[str, Any] | None:
        if not self.pinned_skills:
            return None

        return {"pinned_skills": self.pinned_skills}

def before_agent(
