def search_symbol(query: str) -> list[dict]:
    symbols = json.loads(INDEX_PATH.read_text(encoding="utf-8"))
    query = query.casefold()

    return [
        symbol
        for symbol in symbols
        if query in symbol["qualified_name"].casefold()
        or query in symbol["symbol"].casefold()
    ]

